<template><div class="mvp-coach-state" id="coach-allowance-status"><section v-if="member.unlimited" class="mvp-coach-event"><sf-badge tone="accent">Limited-time event</sf-badge><p>Unlimited conversations until {{ date(member.campaignEndsAt) }}. Regular allowance applies after the event.</p></section><section v-else-if="member.campaignEnded&&member.percent>0" class="mvp-coach-event"><p>The unlimited event has ended. Your {{ member.percent }}% remaining allowance now applies.</p></section><sf-feedback v-if="state==='chat-error'" tone="error" title="Couldn’t get a reply" description="Your draft is still here. No conversation allowance was deducted for this failed request." action="Try again" @action="$emit('action','send')"/><div v-else-if="state==='thinking'" class="mvp-coach-thinking" role="status">AI Coach is preparing your reply<span aria-hidden="true">•••</span></div><sf-feedback v-else-if="member.percent===null&amp;&amp;!member.unlimited" tone="info" title="Allowance temporarily unavailable" description="You can keep writing. Check your allowance before sending; your draft stays here." action="Check allowance" @action="$emit('action','quota-options')"/><sf-feedback v-else-if="member.percent===0&amp;&amp;!member.unlimited" tone="info" :title="member.campaignEnded?'Your unlimited event has ended':'Conversation allowance used up'" :description="member.active?'Your Premium is still active. Keep your draft here and view your allowance. Your training benefits remain available.':'Get a new finite AI Coach allowance when you subscribe to Premium. Keep writing here, or review your options.'" :action="member.active?'View allowance':'See Premium options'" @action="$emit('action','quota-options')"/><section v-if="['plan-preview','plan-active'].includes(state)" class="mvp-dynamic-preview"><sf-badge :tone="state==='plan-active'?'success':'neutral'">{{ state==='plan-active'?'Plan activated':'Dynamic Plan preview' }}</sf-badge><h3>Your next step, with a little structure.</h3><p>Preview your training direction with AI Coach. Activate your saved Dynamic Plan when you’re ready to follow it.</p><ul><li>Bring your training goal into focus</li><li>Keep your upcoming sessions together</li><li>Use your saved plan as a starting point</li></ul><sf-button :disabled="state==='plan-active'" @click="$emit('action','activate-plan')">{{ state==='plan-active'?'Plan is active':'Activate Plan' }}</sf-button><small>{{ member.active?'Included with Premium. Activation uses no conversation allowance.':'Premium is required to activate. Discussing a plan uses your conversation allowance.' }}</small></section></div></template>
<script>import {SfBadge,SfFeedback,SfButton} from '@/design-system';import {membershipDate} from './membership-view';export default{components:{SfBadge,SfFeedback,SfButton},props:{state:String,member:Object},methods:{date:membershipDate}}</script>
<style scoped>.mvp-coach-state{display:grid;gap:12px;margin-bottom:18px}.mvp-coach-event{background:var(--sf-content-surface);border:1px solid var(--sf-content-edge);border-radius:16px;padding:12px}.mvp-coach-event p{font-size:12px;line-height:19px;color:var(--sf-text-secondary);margin:5px 0 0}.mvp-coach-thinking{padding:20px;border-radius:18px;background:var(--sf-content-surface);font-size:13px;line-height:1.6}.mvp-coach-thinking>span{display:block;letter-spacing:5px;color:var(--sf-action);margin-top:8px}.mvp-dynamic-preview{padding:18px 16px;background:var(--sf-content-surface);border:1px solid var(--sf-content-edge);border-radius:20px}.mvp-dynamic-preview h3{font-size:19px;line-height:26px;margin:14px 0 9px;letter-spacing:-.3px}.mvp-dynamic-preview p,.mvp-dynamic-preview li{font-size:13px;line-height:21px;color:var(--sf-text-secondary)}.mvp-dynamic-preview ul{padding-left:18px;margin:12px 0 18px}.mvp-dynamic-preview small{display:block;font-size:11px;line-height:18px;margin-top:10px;color:var(--sf-text-secondary)}.mvp-coach-state:empty{display:none}</style>
